export interface HttpErrorInit {
  message: string;
  status: number;
  code?: string;
  details?: unknown;
  cause?: unknown;
}

export class HttpError extends Error {
  readonly status: number;
  readonly code: string;
  readonly details?: unknown;

  constructor({ message, status, code, details, cause }: HttpErrorInit) {
    super(message, { cause });
    this.name = 'HttpError';
    this.status = status;
    this.code = code ?? `HTTP_${status}`;
    this.details = details;
  }
}

export type ErrorLikeBody = {
  message?: unknown;
  status?: unknown;
  code?: unknown;
  details?: unknown;
};

export function normalizeError({
  status,
  statusText,
  body,
  cause,
}: {
  status: number;
  statusText?: string;
  body?: ErrorLikeBody | null;
  cause?: unknown;
}): HttpError {
  const parsedMessage =
    typeof body?.message === 'string' && body.message.trim().length > 0
      ? body.message.trim()
      : statusText && statusText.trim().length > 0
        ? statusText
        : `Request failed with status ${status}`;

  const parsedCode =
    typeof body?.code === 'string' && body.code.trim().length > 0
      ? body.code.trim()
      : `HTTP_${status}`;

  return new HttpError({
    message: parsedMessage,
    status,
    code: parsedCode,
    details: body?.details,
    cause,
  });
}

import { CSRF_HEADER_NAME, getBrowserCsrfToken } from '@/lib/security/csrf';

import { HttpError, normalizeError } from './errors';

export type FetchJsonInit = RequestInit & {
  parseJson?: (text: string) => unknown;
};

const defaultParseJson = (text: string) => JSON.parse(text) as unknown;

function ensureHeaders(initHeaders?: HeadersInit): Headers {
  const headers = new Headers(initHeaders);
  if (!headers.has('Accept')) {
    headers.set('Accept', 'application/json');
  }
  return headers;
}

export async function fetchJson<T>(input: RequestInfo | URL, init: FetchJsonInit = {}): Promise<T> {
  const { parseJson = defaultParseJson, ...rest } = init;
  const headers = ensureHeaders(rest.headers);
  const csrfToken = getBrowserCsrfToken();
  if (csrfToken && !headers.has(CSRF_HEADER_NAME)) {
    headers.set(CSRF_HEADER_NAME, csrfToken);
  }

  const response = await fetch(input, {
    ...rest,
    headers,
    credentials: rest.credentials ?? 'include',
  });

  const shouldTriggerAuthRedirect = response.status === 401 || response.status === 419;
  if (shouldTriggerAuthRedirect && typeof window !== 'undefined') {
    void import('@/lib/http/sessionRedirect').then((mod) => mod.triggerSessionRedirect()).catch(() => {});
  }

  let text: string | null = null;
  try {
    text = await response.text();
  } catch (cause) {
    if (!response.ok) {
      throw normalizeError({
        status: response.status,
        statusText: response.statusText,
        cause,
      });
    }
    throw new HttpError({
      message: 'Failed to read response body',
      status: response.status,
      code: 'READ_ERROR',
      cause,
    });
  }

  let parsed: unknown = undefined;
  let parseError: unknown = undefined;
  if (text && text.length > 0) {
    try {
      parsed = parseJson(text);
    } catch (cause) {
      parseError = cause;
    }
  }

  if (!response.ok) {
    const errorBody = typeof parsed === 'object' && parsed !== null ? (parsed as Record<string, unknown>) : undefined;
    throw normalizeError({
      status: response.status,
      statusText: response.statusText,
      body: errorBody,
      cause: parseError,
    });
  }

  if (parseError) {
    throw new HttpError({
      message: 'Failed to parse JSON response',
      status: response.status,
      code: 'INVALID_JSON',
      cause: parseError,
    });
  }

  return (parsed as T) ?? (undefined as T);
}

'use client';

export const SESSION_EXPIRED_EVENT = 'session:expired';

let redirectInFlight = false;
let lastPath: string | null = null;
let lastSignalTs = 0;
const SIGNAL_DEBOUNCE_MS = 1500;

export function triggerSessionRedirect(path?: string, message?: string) {
  if (typeof window === 'undefined') return;

  const currentPath = path ?? `${window.location.pathname}${window.location.search}`;
  if (!currentPath || currentPath.startsWith('/auth')) return;

  if (redirectInFlight && lastPath === currentPath) return;

  const now = Date.now();
  if (now - lastSignalTs > SIGNAL_DEBOUNCE_MS) {
    window.dispatchEvent(
      new CustomEvent(SESSION_EXPIRED_EVENT, {
        detail: {
          message: message ?? 'Please sign in again to continue.',
          path: currentPath,
        },
      }),
    );
    lastSignalTs = now;
  }

  const target = `/auth/signin?redirectedFrom=${encodeURIComponent(currentPath)}`;
  redirectInFlight = true;
  lastPath = currentPath;
  window.location.assign(target);
}

import { resolveCookieDomain } from '@/lib/supabase/cookies';

export const OPS_ACTIVE_RESTAURANT_STORAGE_KEY = 'ops.activeRestaurantId';
export const OPS_ACTIVE_RESTAURANT_COOKIE_NAME = 'ops-active-restaurant';

const OPS_ACTIVE_RESTAURANT_MAX_AGE_SECONDS = 60 * 60 * 24 * 30;

function deriveRootDomain(hostname: string): string | undefined {
  if (!hostname || hostname === 'localhost' || hostname.startsWith('127.')) {
    return undefined;
  }

  const parts = hostname.split('.');
  if (parts.length < 2) {
    return undefined;
  }

  return parts.slice(-2).join('.');
}

function resolveBrowserRootDomain(): string | undefined {
  if (typeof window === 'undefined') {
    return undefined;
  }

  const configuredRootDomain = process.env.NEXT_PUBLIC_ROOT_DOMAIN?.trim();
  if (configuredRootDomain && configuredRootDomain !== 'localhost') {
    return configuredRootDomain;
  }

  return deriveRootDomain(window.location.hostname);
}

export function resolvePreferredOpsRestaurantId(
  restaurantIds: readonly string[],
  preferredRestaurantId?: string | null,
): string | null {
  if (preferredRestaurantId && restaurantIds.includes(preferredRestaurantId)) {
    return preferredRestaurantId;
  }

  return restaurantIds[0] ?? null;
}

export function writeBrowserOpsRestaurantCookie(restaurantId: string | null): void {
  if (typeof document === 'undefined') {
    return;
  }

  const secure = typeof window !== 'undefined' ? window.location.protocol === 'https:' : false;
  const rootDomain = resolveBrowserRootDomain();
  const resolvedDomain = resolveCookieDomain(rootDomain);
  const maxAge = restaurantId ? OPS_ACTIVE_RESTAURANT_MAX_AGE_SECONDS : 0;
  const encodedValue = restaurantId ? encodeURIComponent(restaurantId) : '';
  const attributes = [
    `max-age=${maxAge}`,
    'path=/',
    'samesite=lax',
    resolvedDomain ? `domain=${resolvedDomain}` : null,
    secure ? 'secure' : null,
  ]
    .filter(Boolean)
    .join('; ');

  document.cookie = `${OPS_ACTIVE_RESTAURANT_COOKIE_NAME}=${encodedValue}; ${attributes}`;
}

export const RESTAURANT_ROLE_OWNER = 'owner' as const;
export const RESTAURANT_ROLE_MANAGER = 'manager' as const;
export const RESTAURANT_ROLE_HOST = 'host' as const;
export const RESTAURANT_ROLE_SERVER = 'server' as const;

export const RESTAURANT_ROLES = [
  RESTAURANT_ROLE_OWNER,
  RESTAURANT_ROLE_MANAGER,
  RESTAURANT_ROLE_HOST,
  RESTAURANT_ROLE_SERVER,
] as const;

export type RestaurantRole = (typeof RESTAURANT_ROLES)[number];

export const RESTAURANT_ROLE_OPTIONS = RESTAURANT_ROLES.slice() as [
  RestaurantRole,
  ...RestaurantRole[],
];

export const RESTAURANT_ADMIN_ROLES = [RESTAURANT_ROLE_OWNER, RESTAURANT_ROLE_MANAGER] as const;

export type RestaurantAdminRole = (typeof RESTAURANT_ADMIN_ROLES)[number];

export const INVITABLE_ROLES_BY_ACTOR_ROLE = {
  [RESTAURANT_ROLE_OWNER]: RESTAURANT_ROLES,
  [RESTAURANT_ROLE_MANAGER]: [
    RESTAURANT_ROLE_MANAGER,
    RESTAURANT_ROLE_HOST,
    RESTAURANT_ROLE_SERVER,
  ],
  [RESTAURANT_ROLE_HOST]: [],
  [RESTAURANT_ROLE_SERVER]: [],
} as const satisfies Record<RestaurantRole, readonly RestaurantRole[]>;

export function isRestaurantRole(value: string | null | undefined): value is RestaurantRole {
  return typeof value === 'string' && RESTAURANT_ROLES.includes(value as RestaurantRole);
}

export function isRestaurantAdminRole(
  value: string | null | undefined,
): value is RestaurantAdminRole {
  return typeof value === 'string' && RESTAURANT_ADMIN_ROLES.includes(value as RestaurantAdminRole);
}

export function getInvitableRolesForActorRole(
  actorRole: RestaurantRole,
): readonly RestaurantRole[] {
  return INVITABLE_ROLES_BY_ACTOR_ROLE[actorRole];
}

export function canInviteRestaurantRole(
  actorRole: RestaurantRole,
  invitedRole: RestaurantRole,
): boolean {
  return getInvitableRolesForActorRole(actorRole).includes(invitedRole);
}

