                          {item.value}
                        </Badge>
                        {item.description ? (
                          <span className="min-w-0 text-xs text-muted-foreground">
                            {item.description}
                          </span>
                        ) : null}
                      </dd>
                    </div>
                  );
                })}
              </dl>
            </CardContent>
          ) : null}
        </Card>
      ) : null}

      <SettingsSectionNav
        title={railTitle}
        description={railDescription}
        items={railItems}
        footer={footer}
      />

      <div className="flex min-w-0 flex-col gap-4">{children}</div>
    </motion.section>
  );
}

