];

export const SEATING_TYPE_OPTIONS: { value: TableInventory['seatingType']; label: string }[] = [
  { value: 'standard', label: 'Standard' },
  { value: 'sofa', label: 'Sofa' },
  { value: 'booth', label: 'Booth' },
  { value: 'high_top', label: 'High-top' },
